 * This adapter wraps supabase-db.ts functions to provide camelCase property names
 * that are compatible with the existing routers.ts code.
 */

import * as supabaseDb from './supabase-db';
import { generalLog } from './_core/logger';

// ============ Type Converters ============

function snakeToCamel(str: string): string {
  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
}

function convertKeysToCamel<T extends Record<string, unknown>>(obj: T): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[snakeToCamel(key)] = obj[key];
