// ============ User Functions ============

export async function upsertUser(userData: {
  openId: string;
  name?: string | null;
  email?: string | null;
  loginMethod?: string | null;
  passwordHash?: string | null;
  role?: 'admin' | 'user';
  lastSignedIn?: Date;
}): Promise<User | null> {
  // Build the upsert payload from ONLY the fields the caller actually provided.
  // PostgREST upsert (resolution=merge-duplicates) updates exactly the columns
  // present in the payload on conflict and leaves omitted columns UNCHANGED, so
  // partial updates (e.g. the per-request `last_signed_in` touch from
  // authenticateRequest, which passes only openId + lastSignedIn) must NOT carry
  // name/email/role — otherwise an existing user's profile and, critically, an
  // admin's `role` would be clobbered to defaults on every login/request.
  //
  // `role` is only written when explicitly provided, else self-healed to 'admin'
  // for the owner openId; otherwise it is omitted so the existing value is
  // preserved on conflict (and falls back to the column default 'user' on a true
  // insert). Mirrors the role-preservation + owner self-heal in server/db.ts.
  const payload: Record<string, unknown> = {
    open_id: userData.openId,
    last_signed_in: userData.lastSignedIn?.toISOString() ?? new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  if (userData.name !== undefined) payload.name = userData.name ?? null;
  if (userData.email !== undefined) payload.email = userData.email ?? null;
  if (userData.loginMethod !== undefined) payload.login_method = userData.loginMethod ?? null;
  if (userData.passwordHash !== undefined) payload.password_hash = userData.passwordHash ?? null;
  if (userData.role !== undefined) {
    payload.role = userData.role;
  } else if (userData.openId && userData.openId === ENV.ownerOpenId) {
    payload.role = 'admin';
  }

  const { data, error } = await supabase
    .from('users')
    .upsert(payload, {
      onConflict: 'open_id',
    })
    .select()
    .single();

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error upserting user');
    return null;
  }
  return data;
}

