}

export async function logLeadActivity(
  leadId: number,
  activityType: string,
  metadata: Record<string, unknown> = {}
): Promise<boolean> {
  const { error } = await supabase
    .from('lead_activities')
    .insert({
      lead_id: leadId,
      activity_type: activityType,
      metadata,
    });

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error logging lead activity');
    return false;
  }
  return true;
}

export async function getLeadActivities(leadId: number, limit: number = 50): Promise<LeadActivity[]> {
  const { data, error } = await supabase
    .from('lead_activities')
    .select('*')
    .eq('lead_id', leadId)
    .order('created_at', { ascending: false })
    .limit(limit);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error getting lead activities');
    return [];
