export async function findExistingPattern(userId: number, externalUserId: string, patternType: string): Promise<EmotionalPattern | null> {
  const { data, error } = await supabase
    .from('emotional_patterns')
    .select('*')
    .eq('user_id', userId)
    .eq('external_user_id', externalUserId)
    .eq('pattern_type', patternType)
    .single();

  if (error) {
    if (error.code !== 'PGRST116') { // Not found is not an error
      dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error finding emotional pattern');
    }
    return null;
  }
  return data;
}

export async function updateEmotionalPattern(
  patternId: number,
  updates: {
    description?: string;
    triggers?: string | null;
    recommendedApproach?: string | null;
    frequency?: number;
  }
): Promise<boolean> {
  const updateData: Record<string, unknown> = {
    updated_at: new Date().toISOString(),
  };

  if (updates.description !== undefined) {
    updateData.description = updates.description;
  }
  if (updates.triggers !== undefined) {
    updateData.triggers = updates.triggers;
  }
  if (updates.recommendedApproach !== undefined) {
    updateData.recommended_approach = updates.recommendedApproach;
  }
  if (updates.frequency !== undefined) {
    updateData.frequency = updates.frequency;
  }

  const { error } = await supabase
    .from('emotional_patterns')
    .update(updateData)
    .eq('id', patternId);

  if (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Supabase] Error updating emotional pattern');
    return false;
  }
  return true;
}

