                    </DialogTrigger>
                    <DialogContent>
                      <DialogHeader>
                        <DialogTitle>Create API key</DialogTitle>
                        <DialogDescription>
                          Give your key a name to identify where it's used (e.g. "Production", "CI/CD").
                        </DialogDescription>
                      </DialogHeader>
                      <div className="space-y-2 py-2">
                        <Label htmlFor="key-name">Key name (optional)</Label>
                        <Input
                          aria-label="e.g. Production" id="key-name"
                          placeholder="e.g. Production"
